  const tiles = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE);
  tiles.fill(TILE_FLOOR);

  for (let y = 4; y <= 8; y++) {
    for (let x = 4; x <= 8; x++) {
      const border = x === 4 || x === 8 || y === 4 || y === 8;
      tiles[y * CHUNK_SIZE + x] = border ? TILE_WALL : TILE_FLOOR;
